{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "refresh",
    "backend_id": "backend_001",
    "widgets_json": {
      "vix_history": {
        "data": {
          "table": {
            "columnsDefs": [
              {
                "cellDataType": "dateString",
                "field": "date",
                "headerName": "Date"
              },
              {
                "cellDataType": "number",
                "field": "close",
                "headerName": "Close"
              },
              {
                "cellDataType": "number",
                "field": "return_pct",
                "formatterFn": "percent",
                "headerName": "Return %",
                "renderFn": "greenRed"
              }
            ]
          }
        },
        "description": "Daily CBOE VIX closes with returns.",
        "endpoint": "/vix-history",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "VIX History",
        "params": [
          {
            "label": "Window",
            "max": 365,
            "min": 5,
            "paramName": "window",
            "type": "number",
            "value": 30
          }
        ],
        "type": "table"
      },
      "vix_term_structure": {
        "description": "Plotly curve of VIX futures by expiry.",
        "endpoint": "/vix-term-structure",
        "gridData": {
          "h": 9,
          "w": 20
        },
        "name": "VIX Term Structure",
        "raw": true,
        "type": "chart"
      },
      "vol_regime_metric": {
        "description": "Current volatility regime score.",
        "endpoint": "/vol-regime",
        "gridData": {
          "h": 4,
          "w": 6
        },
        "name": "Vol Regime",
        "type": "metric"
      }
    },
    "apps_json": [
      {
        "name": "Vol Morning",
        "description": "Vol level, structure, regime.",
        "prompts": [
          "What changed in the term structure overnight?",
          "Summarize the vol regime in one line."
        ],
        "tabs": {
          "morning": {
            "id": "morning",
            "name": "Morning",
            "layout": [
              {
                "i": "vix_history",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9,
                "state": {
                  "params": {
                    "window": 30
                  }
                }
              },
              {
                "i": "vix_term_structure",
                "x": 20,
                "y": 0,
                "w": 12,
                "h": 9
              },
              {
                "i": "vol_regime_metric",
                "x": 32,
                "y": 0,
                "w": 8,
                "h": 6
              }
            ]
          }
        }
      }
    ]
  }
}
